def get_most_assigned_bug_person(repo):
    assignee_counts = Counter()
    offset = 0
    limit = 50

    while True:
        # Fetch open issues (we'll filter for 'bug' label manually to be safe)
        issues_data = list_issues(repo=repo, state='open', limit=limit, offset=offset)

        # The response structure is {'total': X, 'items': [...]}
        issues = issues_data.get('items', [])

        if not issues:
            break

        for issue in issues:
            # Check if the label is 'bug'
            if issue.get('label') == 'bug':
                assignee_id = issue.get('assignee')
                if assignee_id:
                    assignee_counts[assignee_id] += 1

        if len(issues) < limit:
            break
        offset += limit

    if not assignee_counts:
        return "No bugs found"

    # Get the most frequent assignee_id
    most_common_id = assignee_counts.most_common(1)[0][0]

    # Look up the user's name
    user_info = lookup_user(user_id=most_common_id)
    return user_info.get('name')

